      input.addEventListener("input", () => {
        if (timer !== null) {
          clearTimeout(timer);
        }
        timer = setTimeout(() => {
          timer = null;
          persistActionDelay(input.value);
        }, 250);
      });
      input.addEventListener("change", () => persistActionDelay(input.value));
      applyActionDelayField();
